    <style data-savepage-href="css/style.min.css">:root{--bg-purple:#CD92C1;--accent-yellow:#FFCF01;--card-cream:#FFF1D0;--text-dark:#483735;--text-light:#FFFDEB;--border-color:#513F3D;--ivory-2:#FFF7E1;--congo-light:#66504D;--teal:#99D6CC;--rose:#F79F99;--rose-deep:#F75454;--lavender:#D9ACD0;--yellow-light:#FFE18B;--border-width:3px;--shadow-sm:4px 4px 0px var(--border-color);--shadow-md:6px 6px 0px var(--border-color);--shadow-lg:10px 10px 0px var(--border-color);--shadow-xl:14px 14px 0px var(--border-color);--radius-sm:10px;--radius-md:16px;--radius-lg:24px;--container-max:1360px;--section-pad:clamp(40px,8vh,90px);--navbar-h:76px}html.no-scroll,body.no-scroll{overflow:hidden !important;height:100%}html.site-loading .site-content,html.site-loading #distributor-popup{display:none !important}html.site-ready .site-content{display:block}html.site-ready .hero-section{animation:hero-section-in 0.9s cubic-bezier(0.16,1,0.3,1) 0.05s both}@keyframes hero-section-in{from{opacity:0;transform:translateY(28px)}to{opacity:1;transform:translateY(0)}}html.preloader-active #preloader{display:flex !important}#preloader:not(.preloader-ready) .preloader-gabru-ring,#preloader:not(.preloader-ready) .preloader-stage{visibility:hidden;opacity:0}#preloader.preloader-ready .preloader-gabru-ring,#preloader.preloader-ready .preloader-stage{visibility:visible;opacity:1}#preloader{--preloader-ease-out:cubic-bezier(0.16,1,0.3,1);--preloader-ease-in:cubic-bezier(0.77,0,0.175,1);--preloader-gabru-shadow:drop-shadow(4px 4px 0px var(--border-color));position:fixed;inset:0;z-index:99999;background-color:var(--accent-yellow);display:flex;align-items:center;justify-content:center;overflow:hidden;isolation:isolate}#preloader.preloader-exit{animation:preloader-overlay-out var(--preloader-exit-ms,850ms) var(--preloader-ease-in) forwards;pointer-events:none}#preloader.preloader-exit .preloader-gabru,#preloader.preloader-exit .preloader-logo,#preloader.preloader-exit .preloader-bar-bg,#preloader.preloader-exit .preloader-percent,#preloader.preloader-exit .preloader-bg,#preloader.preloader-exit .preloader-grain{animation:preloader-unified-out var(--preloader-exit-ms,850ms) var(--preloader-ease-in) 0s forwards}#preloader.preloader-exit .preloader-gabru{animation-name:preloader-gabru-out}#preloader.preloader-ready:not(.preloader-complete) .preloader-gabru,#preloader.preloader-ready:not(.preloader-complete) .preloader-logo,#preloader.preloader-ready:not(.preloader-complete) .preloader-bar-bg,#preloader.preloader-ready:not(.preloader-complete) .preloader-percent{visibility:visible !important}#preloader.preloader-ready:not(.preloader-complete) .preloader-gabru,#preloader.preloader-ready:not(.preloader-complete) .preloader-logo,#preloader.preloader-ready:not(.preloader-complete) .preloader-bar-bg{opacity:1 !important}#preloader.preloader-hidden{display:none}.preloader-bg{position:absolute;inset:-20%;z-index:0;background:radial-gradient(ellipse 80% 60% at 20% 30%,rgba(217,172,208,0.55) 0%,transparent 55%),radial-gradient(ellipse 70% 55% at 85% 70%,rgba(153,214,204,0.45) 0%,transparent 50%),radial-gradient(ellipse 60% 50% at 50% 100%,rgba(247,159,153,0.35) 0%,transparent 45%);animation:preloader-bg-drift 8s ease-in-out infinite alternate}.preloader-grain{position:absolute;inset:0;z-index:1;opacity:0.04;pointer-events:none;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E")}@keyframes preloader-bg-drift{0%{transform:scale(1) rotate(0deg)}100%{transform:scale(1.08) rotate(3deg)}}@keyframes preloader-overlay-out{to{opacity:0;visibility:hidden}}@keyframes preloader-unified-in{0%{opacity:0;transform:scale(0.9) translateY(18px)}100%{opacity:1;transform:scale(1) translateY(0)}}@keyframes preloader-gabru-in{0%{opacity:0;transform:scale(0.9) translateY(18px);filter:blur(4px) var(--preloader-gabru-shadow)}100%{opacity:1;transform:scale(1) translateY(0);filter:var(--preloader-gabru-shadow)}}@keyframes preloader-unified-out{to{opacity:0;transform:scale(0.96) translateY(-14px)}}@keyframes preloader-gabru-out{to{opacity:0;transform:scale(0.96) translateY(-14px);filter:blur(4px) var(--preloader-gabru-shadow)}}#preloader.preloader-ready .preloader-gabru{animation:preloader-gabru-in var(--preloader-enter-ms,650ms) var(--preloader-ease-out) 0s forwards}#preloader.preloader-ready .preloader-logo,#preloader.preloader-ready .preloader-bar-bg{animation:preloader-unified-in var(--preloader-enter-ms,650ms) var(--preloader-ease-out) 0s forwards}@keyframes preloader-percent-in{0%{opacity:0;transform:scale(0.9) translateY(18px)}100%{opacity:0.7;transform:scale(1) translateY(0)}}#preloader.preloader-ready .preloader-percent{animation:preloader-percent-in var(--preloader-enter-ms,650ms) var(--preloader-ease-out) 0s forwards}.preloader-stage{position:relative;z-index:4;display:flex;align-items:center;justify-content:center;pointer-events:none}.preloader-gabru-ring{position:absolute;inset:0;pointer-events:none;z-index:3}.preloader-gabru-slot{position:absolute;width:clamp(64px,11vw,96px);display:flex;align-items:flex-end;justify-content:center}.preloader-gabru-slot--1{top:5%;left:4%}.preloader-gabru-slot--2{top:6%;left:22%}.preloader-gabru-slot--3{top:5%;right:4%}.preloader-gabru-slot--4{top:48%;left:3%;transform:translateY(-50%)}.preloader-gabru-slot--5{top:48%;right:3%;transform:translateY(-50%)}.preloader-gabru-slot--6{bottom:7%;left:4%}.preloader-gabru-slot--7{bottom:8%;left:24%}.preloader-gabru-slot--8{bottom:8%;right:24%}.preloader-gabru-slot--9{bottom:7%;right:4%}.preloader-gabru{display:block;width:100%;height:auto;object-fit:contain;opacity:0;filter:var(--preloader-gabru-shadow);will-change:transform,opacity,filter}.preloader-inner{position:relative;z-index:3;display:flex;flex-direction:column;align-items:center;gap:36px}.preloader-logo-wrap{display:flex;align-items:center;justify-content:center}.preloader-logo{height:clamp(72px,14vw,110px);width:auto;display:block;opacity:0;will-change:transform,opacity}.preloader-progress{display:flex;flex-direction:column;align-items:center;width:100%}.preloader-bar-bg{width:360px;max-width:85vw;height:32px;background:var(--card-cream);border:var(--border-width) solid var(--border-color);border-radius:50px;margin:0 auto;overflow:hidden;box-shadow:var(--shadow-sm);opacity:0}.preloader-bar-fill{position:relative;height:100%;width:0%;background:linear-gradient(90deg,var(--bg-purple) 0%,#e8b4dc 50%,var(--bg-purple) 100%);background-size:200% 100%}#preloader.preloader-ready .preloader-bar-fill{animation:preloader-bar-fill var(--preloader-duration,2400ms) cubic-bezier(0.65,0,0.35,1) var(--preloader-enter-ms,650ms) forwards,preloader-bar-gradient 1.8s ease-in-out var(--preloader-enter-ms,650ms) infinite}@keyframes preloader-bar-fill{to{width:100%}}@keyframes preloader-bar-gradient{0%,100%{background-position:0% 50%}50%{background-position:100% 50%}}.preloader-bar-shine{position:absolute;top:0;left:-40%;width:40%;height:100%;background:linear-gradient(90deg,transparent,rgba(255,255,255,0.55),transparent)}#preloader.preloader-ready .preloader-bar-shine{animation:preloader-bar-shine 1.4s ease-in-out calc(var(--preloader-enter-ms,650ms) + 200ms) infinite}@keyframes preloader-bar-shine{0%{left:-40%}100%{left:140%}}.preloader-percent{margin-top:12px;font-family:'Libre Franklin',sans-serif;font-size:0.85rem;font-weight:700;letter-spacing:0.2em;color:var(--text-dark);opacity:0}@media (prefers-reduced-motion:reduce){#preloader.preloader-ready .preloader-gabru,#preloader.preloader-ready .preloader-logo,#preloader.preloader-ready .preloader-bar-bg,#preloader.preloader-exit .preloader-gabru,#preloader.preloader-exit .preloader-logo,#preloader.preloader-exit .preloader-bar-bg{animation-duration:0.35s !important;animation-iteration-count:1 !important}ht